12: exports.expressCreateServer = function (hook_name, args, cb) {
13:   //init socket.io and redirect all requests to the MessageHandler
14:   var io = socketio.listen(args.app);
15: 
16:   /* Require an express session cookie to be present, and load the
17:    * session. See http://www.danielbaulig.de/socket-ioexpress for more
18:    * info */
19:   io.set('authorization', function (data, accept) {
20:     if (!data.headers.cookie) return accept('No session cookie transmitted.', false);
21:     data.cookie = connect.utils.parseCookie(data.headers.cookie);
22:     data.sessionID = data.cookie.express_sid;
23:     args.app.sessionStore.get(data.sessionID, function (err, session) {
24:       if (err || !session) return accept('Bad session / session has expired', false);
25:       data.session = new connect.middleware.session.Session(data, session);
26:       accept(null, true);
27:     });
28:   });
