1: var express = require('express');
2: var log4js = require('log4js');
3: var httpLogger = log4js.getLogger("http");
4: var settings = require('../../utils/Settings');
5: var randomString = require('ep_etherpad-lite/static/js/pad_utils').randomString;
6: var hooks = require('ep_etherpad-lite/static/js/pluginfw/hooks');
7: 
8: 
9: //checks for basic http auth
10: exports.basicAuth = function (req, res, next) {
11:  var authorize = function (cb) {
12:     // Do not require auth for static paths...this could be a bit brittle
13:     if (req.path.match(/^\/(static|javascripts|pluginfw)/)) return cb(true);
14: 
15:     if (req.path.indexOf('/admin') != 0) {
16:       if (!settings.requireAuthentication) return cb(true);
17:       if (!settings.requireAuthorization && req.session && req.session.user) return cb(true);
18:     }
19: 
20:     if (req.session && req.session.user && req.session.user.is_admin) return cb(true);
21: 
22:     // hooks.aCallFirst("authorize", {resource: req.path, req: req}, cb);
23:     cb(false);
24:   }
25: 
26:   var authenticate = function (cb) {
27:     // If auth headers are present use them to authenticate...
28:     if (req.headers.authorization && req.headers.authorization.search('Basic ') === 0) {
29:       var userpass = new Buffer(req.headers.authorization.split(' ')[1], 'base64').toString().split(":")
30:       var username = userpass[0];
31:       var password = userpass[1];
32: 
33:       if (settings.users[username] != undefined && settings.users[username].password == password) {
34:         settings.users[username].username = username;
35:         req.session.user = settings.users[username];
36:         return cb(true);
37:       }
38:       // return hooks.aCallFirst("authenticate", {req: req, username: username, password: password}, cb);
39:     }
40:     // hooks.aCallFirst("authenticate", {req: req}, cb);
41:     cb(false);
42:   }
43: 
44: 
45:   var failure = function () {
46:     /* Authentication OR authorization failed. Return Auth required
47:      * Headers, delayed for 1 second, if authentication failed. */
48:     res.header('WWW-Authenticate', 'Basic realm="Protected Area"');
49:     if (req.headers.authorization) {
50:       setTimeout(function () {
51:         res.send('Authentication required', 401);
52:       }, 1000);
53:     } else {
54:       res.send('Authentication required', 401);
55:     }
56:   }
57: 
58: 
59:   /* This is the actual authentication/authorization hoop. It is done in four steps:
60: 
61:      1) Try to just access the thing
62:      2) If not allowed using whatever creds are in the current session already, try to authenticate
63:      3) If authentication using already supplied credentials succeeds, try to access the thing again
64:      4) If all els fails, give the user a 401 to request new credentials
65: 
66:      Note that the process could stop already in step 3 with a redirect to login page.
67: 
68:   */
69:  
70:   authorize(function (ok) {
71:     if (ok) return next();
72:     authenticate(function (ok) {
73:       if (!ok) return failure();
74:       authorize(function (ok) {
75:         if (ok) return next();
76:         failure();
77:       });
78:     });
79:   });
80: }
