82: exports.expressConfigure = function (hook_name, args, cb) {
83:   // If the log level specified in the config file is WARN or ERROR the application server never starts listening to requests as reported in issue #158.
84:   // Not installing the log4js connect logger when the log level has a higher severity than INFO since it would not log at that level anyway.
85:   if (!(settings.loglevel === "WARN" || settings.loglevel == "ERROR"))
86:     args.app.use(log4js.connectLogger(httpLogger, { level: log4js.levels.INFO, format: ':status, :method :url'}));
87:   args.app.use(express.cookieParser());
88: 
89:   /* Do not let express create the session, so that we can retain a
90:    * reference to it for socket.io to use. Also, set the key (cookie
91:    * name) to a javascript identifier compatible string. Makes code
92:    * handling it cleaner :) */
93: 
94:   args.app.sessionStore = new express.session.MemoryStore();
95:   args.app.use(express.session({store: args.app.sessionStore,
96:                                 key: 'express_sid',
97:                                 secret: apikey = randomString(32)}));
98: 
99:   args.app.use(exports.basicAuth);
100: }

