22: var fs = require("fs");
23: var os = require("os");
24: var path = require('path');
25: var argv = require('./Cli').argv;
26: var npm = require("npm/lib/npm.js");
27: 
28: /* Root path of the installation */
29: exports.root = path.normalize(path.join(npm.dir, ".."));
30: 
31: /**
32:  * The IP ep-lite should listen to
33:  */
34: exports.ip = "0.0.0.0";
35:   
36: /**
37:  * The Port ep-lite should listen to
38:  */
39: exports.port = 9001;
40: /*
41:  * The Type of the database
42:  */
43: exports.dbType = "dirty";
44: /**
45:  * This setting is passed with dbType to ueberDB to set up the database
46:  */
47: exports.dbSettings = { "filename" : path.join(exports.root, "var/dirty.db") };
48: /**
49:  * The default Text of a new pad
50:  */
51: exports.defaultPadText = "Welcome to Etherpad Lite!\n\nThis pad text is synchronized as you type, so that everyone viewing this page sees the same text. This allows you to collaborate seamlessly on documents!\n\nEtherpad Lite on Github: http:\/\/j.mp/ep-lite\n";
52: 
53: /**
54:  * A flag that requires any user to have a valid session (via the api) before accessing a pad
55:  */
56: exports.requireSession = false;
57: 
58: /**
59:  * A flag that prevents users from creating new pads
60:  */
61: exports.editOnly = false;
62: 
63: /**
64:  * Max age that responses will have (affects caching layer).
65:  */
66: exports.maxAge = 1000*60*60*6; // 6 hours
67: 
68: /**
69:  * A flag that shows if minification is enabled or not
70:  */
71: exports.minify = true;
72: 
73: /**
74:  * The path of the abiword executable
75:  */
76: exports.abiword = null;
77: 
78: /**
79:  * The log level of log4js
80:  */
81: exports.loglevel = "INFO";
82: 
83: /* This setting is used if you need authentication and/or
84:  * authorization. Note: /admin always requires authentication, and
85:  * either authorization by a module, or a user with is_admin set */
86: exports.requireAuthentication = false;
87: exports.requireAuthorization = false;
88: exports.users = {};
89: 
90: //checks if abiword is avaiable
91: exports.abiwordAvailable = function()
92: {
93:   if(exports.abiword != null)
94:   {
95:     return os.type().indexOf("Windows") != -1 ? "withoutPDF" : "yes";
96:   }
97:   else
98:   {
99:     return "no";
100:   }
101: }
102: 
103: // Discover where the settings file lives
104: var settingsFilename = argv.settings || "settings.json";
105: if (settingsFilename.charAt(0) != '/') {
106:     settingsFilename = path.normalize(path.join(root, settingsFilename));
107: }
108: 
109: //read the settings sync
110: var settingsStr = fs.readFileSync(settingsFilename).toString();
111: 
112: //remove all comments
113: settingsStr = settingsStr.replace(/\*([^*]|[\r\n]|(\*+([^*/]|[\r\n])))*\*+/gm,"").replace(/#.*/g,"").replace(/\/\/.*/g,"");
114: 
115: //try to parse the settings
116: var settings;
117: try
118: {
119:   settings = JSON.parse(settingsStr);
120: }
121: catch(e)
122: {
123:   console.error("There is a syntax error in your settings.json file");
124:   console.error(e.message);
125:   process.exit(1);
126: }
127: 
128: //loop trough the settings
129: for(var i in settings)
130: {
131:   //test if the setting start with a low character
132:   if(i.charAt(0).search("[a-z]") !== 0)
133:   {
134:     console.warn("Settings should start with a low character: '" + i + "'");
135:   }
136: 
137:   //we know this setting, so we overwrite it
138:   if(exports[i] !== undefined)
139:   {
140:     exports[i] = settings[i];
141:   }
142:   //this setting is unkown, output a warning and throw it away
143:   else
144:   {
145:     console.warn("Unkown Setting: '" + i + "'");
146:     console.warn("This setting doesn't exist or it was removed");
147:   }
148: }

