12: exports.expressCreateServer = function (hook_name, args, cb) {
13:   //init socket.io and redirect all requests to the MessageHandler
14:   var io = socketio.listen(args.app);
15: 
16:   /* Require an express session cookie to be present, and load the
17:    * session. See http://www.danielbaulig.de/socket-ioexpress for more
18:    * info */
19:   io.set('authorization', function (data, accept) {
20:     if (!data.headers.cookie) return accept('No session cookie transmitted.', false);
21:     data.cookie = connect.utils.parseCookie(data.headers.cookie);
22:     data.sessionID = data.cookie.express_sid;
23:     args.app.sessionStore.get(data.sessionID, function (err, session) {
24:       if (err || !session) return accept('Bad session / session has expired', false);
25:       data.session = new connect.middleware.session.Session(data, session);
26:       accept(null, true);
27:     });
28:   });
29: 
30: 
31:   //this is only a workaround to ensure it works with all browers behind a proxy
32:   //we should remove this when the new socket.io version is more stable
33:   io.set('transports', ['xhr-polling']);
34: 
35:   var socketIOLogger = log4js.getLogger("socket.io");
36:   io.set('logger', {
37:     debug: function (str)
38:     {
39:       socketIOLogger.debug.apply(socketIOLogger, arguments);
40:     }, 
41:     info: function (str)
42:     {
43:       socketIOLogger.info.apply(socketIOLogger, arguments);
44:     },
45:     warn: function (str)
46:     {
47:       socketIOLogger.warn.apply(socketIOLogger, arguments);
48:     },
49:     error: function (str)
50:     {
51:       socketIOLogger.error.apply(socketIOLogger, arguments);
52:     },
53:   });
54: 
55:   //minify socket.io javascript
56:   if(settings.minify)
57:     io.enable('browser client minification');
58: 
59:   //Initalize the Socket.IO Router
60:   socketIORouter.setSocketIO(io);
61:   socketIORouter.addComponent("pad", padMessageHandler);
62:   socketIORouter.addComponent("timeslider", timesliderMessageHandler);
63: 
64:   hooks.callAll("socketio", {"app": args.app, "io": io});
65: }

